<script lang="ts">import NestedComponents from './NestedComponents.svelte';
let { extensions, children } = $props();
const Extension = extensions[0];
const nextExtensions = extensions.slice(1);
</script>

<Extension>
  {#if nextExtensions.length > 0}
    <NestedComponents extensions={nextExtensions}>
      {@render children()}
    </NestedComponents>
  {:else}
    {@render children()}
  {/if}
</Extension>
